// SPDX-License-Identifier: Apache-2.0
// Fails if any first-party source file lacks the SPDX header on its first line.
import { readdir, readFile } from 'node:fs/promises';
import { join, relative } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;
const HEADER = '// SPDX-License-Identifier: Apache-2.0';
const EXTENSIONS = ['.ts', '.mts', '.cts', '.js', '.mjs', '.cjs'];
const SKIP_DIRS = new Set([
  'node_modules',
  'dist',
  'dist-types',
  '.git',
  'test-results',
  'playwright-report',
  'coverage',
  // Generated by Astro (site/) and wrangler (deploy/sandbox-worker/).
  '.astro',
  '.wrangler',
]);

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name)) yield* walk(join(dir, entry.name));
    } else if (EXTENSIONS.some((ext) => entry.name.endsWith(ext))) {
      yield join(dir, entry.name);
    }
  }
}

const missing = [];
for await (const file of walk(ROOT)) {
  // An executable's shebang must come first, so the header may follow it.
  const [line1, line2] = (await readFile(file, 'utf8')).split('\n', 2);
  const firstLine = line1?.startsWith('#!') ? line2 : line1;
  // Vendored third-party code keeps its own license identifier.
  const vendored =
    (file.includes('/vendor/') && firstLine?.startsWith('// SPDX-License-Identifier: ')) ||
    // Node's own tests, kept byte for byte (line numbers matter); see that directory's LICENSE.
    file.includes('/test/conformance/node-tests/');
  if (firstLine !== HEADER && !vendored) missing.push(relative(ROOT, file));
}

if (missing.length > 0) {
  console.error(`Missing "${HEADER}" on line 1 (after any shebang) of:\n  ${missing.join('\n  ')}`);
  process.exit(1);
}
console.log('SPDX headers OK');
